await writeFile(path.join(gitRepository,'migrations','V2__import.sql'),'ALTER TABLE imported_item ADD name VARCHAR2(40);\n');
git('add','migrations');git('commit','-q','-m','Native local Git fixture');const gitCommit=git('rev-parse','HEAD');
