  await sql`INSERT INTO sf_project_grants(id,organization_id,project_id,actor_id,grant_os_uid) VALUES(${randomUUID()},${org},${project},${reviewer},1000)`;
  await sql`INSERT INTO sf_workspace_database_grants(organization_id,actor_id,operator_os_uid) VALUES(${org},${actor},1000)`;
