  await sql`INSERT INTO sf_database_observations(organization_id,connection_id,operation,status,identity,identity_digest,schemas,limitations,provenance,actor_id,connection_revision) VALUES(${org},${operatorConnection.id},'DISCOVER',${observation.status},${sql.json(observation.identity)},${observation.identityDigest},${sql.json(observation.schemas)},${sql.json(observation.limitations)},${observation.provenance},${actor},1)`;
