  await page.getByRole('button',{name:'Configuration',exact:true}).click();
  await page.locator('#source-repository').selectOption('native-browser');await page.locator('#source-folder').fill('migrations');
  await page.getByRole('button',{name:'Save source binding',exact:true}).click();await page.getByRole('status').filter({hasText:'Source binding saved.'}).waitFor();
  await page.getByText('Add deployment profile',{exact:true}).click();
