  const gitDetail=page.getByRole('region',{name:'Retained release details',exact:true});await gitDetail.waitFor();assert.match(await gitDetail.innerText(),new RegExp(gitCommit));assert.match(await gitDetail.innerText(),/GIT_IMPORT/);assert.equal(await gitDetail.locator('.retained-release-file').count(),2);
  await gitDetail.locator('.retained-release-file').first().getByRole('button',{name:'Preview file statements',exact:true}).click();await page.getByRole('region',{name:'Retained statement preview',exact:true}).waitFor();
