  const revokedDownload=await revokedDownloading;const revokedBundle=JSON.parse(await readFile(await revokedDownload.path(),'utf8'));assert.equal(revokedBundle.sha256,createHash('sha256').update(revokedBundle.record).digest('hex'));
  const revokedRecord=JSON.parse(revokedBundle.record);assert.equal(revokedRecord.plan.status,'REVOKED');assert.equal(revokedRecord.job.state,'CANCELLED');assert.equal(revokedRecord.executionAuthority,false);assert.equal(revokedRecord.attempts.length,0);
